        if (labels.get(i) == minLabel) {
            bucketsByLabel.get(0).add(labels.get(i));
            bucketsByLabel.get(i).remove(labels.get(i));
        }
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Update the labeling accordingly
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) > 0 && labels.get(i) < minLabel) {
            labels.set(i, 0);
        } else if (labels.get(i) <= 0) {
            labels.set(i, minLabel + 1);
        }
    }
}

