private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long sumOfElements = 0;
    int size = bounds.size();

    for (int i = size - 1; i >= 0; i--) {
        suffixSumList.add((i == size - 1) ? bounds.get(i) : suffixSumList.get(i + 1) + bounds.get(i));
        sumOfElements += bounds.get(i);
    }

    return new Pair<>(suffixSumList, sumOfElements);
}

